def hyperop(n: int, a: int, b: int, _guard: int = 10 ** 6) -> int:
    """
    The nth hyperoperation on non-negative integers:
        n=1 add, n=2 multiply, n=3 power, n=4 tetration, n=5 pentation.
    Only sane for tiny inputs -- anything past a toy example is astronomically
    large, so we cap the magnitude and refuse rather than eat all your memory.
    """
    if n == 1:
        return a + b
    if n == 2:
        return a * b
    if n == 3:
        result = a ** b
        if result > _guard:
            raise OverflowError(f"{a}^{b} = {result} exceeds the demo guard")
        return result
    if b == 0:
        return 1
    # n >= 4: fold the (n-1)th operation b times
    acc = a
    for _ in range(b - 1):
        acc = hyperop(n - 1, a, acc, _guard)
    return acc

def call_graph(source: str) -> list[tuple[str, str]]:
    """Return direct calls between functions/methods defined in the same module."""
    tree, error = _parse(source)
    if error is not None:
        return []
    functions = _function_nodes(tree)
    known = {name.split(".")[-1] for name, _ in functions}
    edges = []
    seen = set()
    for caller, node in functions:
        for child in ast.walk(node):
            if not isinstance(child, ast.Call):
                continue
            callee = ""
            if isinstance(child.func, ast.Name):
                callee = child.func.id
            elif isinstance(child.func, ast.Attribute):
                callee = child.func.attr
            edge = (caller, callee)
            if callee in known and callee != caller.split(".")[-1] and edge not in seen:
                seen.add(edge)
                edges.append(edge)
    return edges[:MAX_EDGES]

