def strip_comments(source: str) -> str:
    """Remove C/C++ comments without being fooled by comment-like literals.

    A regex cannot do this correctly: `printLine("/* not a comment */")` would
    lose half the string, and `"\\""` would end it early.  So this walks the
    source once, tracking whether it is inside a string, a character literal or
    a comment, which is short enough to be obviously right.
    """
    out: list[str] = []
    index, length = 0, len(source)
    while index < length:
        char = source[index]
        pair = source[index:index + 2]
        if pair == "/*":
            end = source.find("*/", index + 2)
            index = length if end < 0 else end + 2
            out.append(" ")
        elif pair == "//":
            end = source.find("\n", index)
            index = length if end < 0 else end
            out.append(" ")
        elif char in "\"'":
            quote, start = char, index
            index += 1
            while index < length:
                if source[index] == "\\":
                    index += 2
                    continue
                if source[index] == quote:
                    index += 1
                    break
                if source[index] == "\n" and quote == "\"":
                    break            # unterminated; do not run off the file
                index += 1
            out.append(source[start:index])
        else:
            out.append(char)
            index += 1
    return "".join(out)

def _robots_specificity(pattern: str) -> int:
    """Count path octets, excluding wildcard syntax, for longest-match ties."""
    count = index = 0
    while index < len(pattern):
        if pattern[index] == "*":
            index += 1
        elif pattern[index] == "%" and index + 2 < len(pattern) and re.fullmatch(
                r"[0-9A-F]{2}", pattern[index + 1:index + 3]):
            count += 1
            index += 3
        else:
            count += len(pattern[index].encode("utf-8"))
            index += 1
    return count

