def _read_baseline(path: Path) -> bytes:
    """Reject oversized baselines by metadata, then retain a race-safe read cap."""
    try:
        info = path.stat()
        if not stat.S_ISREG(info.st_mode) or info.st_size > MAX_FILE_BYTES:
            raise RepairDirectorError("baseline file exceeds the size boundary")
        with path.open("rb") as stream:
            raw = stream.read(MAX_FILE_BYTES + 1)
    except RepairDirectorError:
        raise
    except OSError as exc:
        raise RepairDirectorError("baseline file is unavailable") from exc
    if len(raw) > MAX_FILE_BYTES:
        raise RepairDirectorError("baseline file exceeds the size boundary")
    return raw

def _c_bodies(blanked: str):
    """(name, start_line, end_line, body_text) per function/method body. Brace
    matching on blanked code; a body is a '{...}' whose header names a callable."""
    stack = []
    bodies = []
    line = 1
    seg_start = 0
    for i, ch in enumerate(blanked):
        if ch == "\n":
            line += 1
        elif ch == "{":
            stack.append((i, line, _header_name(blanked[seg_start:i])))
            seg_start = i + 1
        elif ch == "}":
            _pop_body(stack, bodies, i, line, blanked)
            seg_start = i + 1
        elif ch == ";":
            seg_start = i + 1
    return bodies

