def _is_local_fixed_root(path: Path) -> bool:
    """Reject UNC, mapped-network, removable, and unknown Windows roots."""
    spelling = os.fspath(path)
    if _looks_network_spelled(spelling):
        return False
    if os.name != "nt":
        # The portable standard library cannot reliably classify a POSIX
        # mount as local or remote.  This module grants no network operation;
        # callers must not present a remote mount as a local enterprise root.
        return True
    anchor = path.anchor
    if not anchor or _looks_network_spelled(anchor):
        return False
    try:
        import ctypes
        # DRIVE_FIXED == 3.  Mapped network, removable, optical, RAM-disk,
        # unknown, and unavailable roots are denied.
        return int(ctypes.windll.kernel32.GetDriveTypeW(anchor)) == 3
    except (AttributeError, OSError, TypeError, ValueError):
        return False

def _file_input_descriptors(values: Sequence[str | os.PathLike[str]]) -> list[dict[str, Any]]:
    """Describe file inputs by content and opaque location, never by file contents."""
    rows: list[dict[str, Any]] = []
    for value in values:
        try:
            path = Path(value).expanduser().resolve(strict=True)
            if not path.is_file():
                raise OSError("not a regular file")
            digest = hashlib.sha256()
            size = 0
            with path.open("rb") as stream:
                while True:
                    block = stream.read(128 * 1024)
                    if not block:
                        break
                    size += len(block)
                    if size > MAX_LEGACY_RULE_PACK_BYTES:
                        raise Attestor41Error("a legacy rule-pack input exceeds the byte boundary")
                    digest.update(block)
        except Attestor41Error:
            raise
        except (OSError, RuntimeError, TypeError, ValueError) as exc:
            raise Attestor41Error("a configured rule-pack input is unavailable") from exc
        rows.append({
            "location_sha256": _sha(os.fspath(path).encode("utf-8", "surrogatepass")),
            "content_sha256": digest.hexdigest(),
            "bytes": size,
        })
    return rows

