def r_signed_size(ctx):
    """Sign extension into a size parameter.

    The defect model is Juliet's CWE-194 and a real one::

        short data;
        data = -1;                     /* or read from input */
        if (data < 100)                /* bounds it above, not below */
            memmove(dest, source, data);

    `data` converts to `size_t` as roughly 2^64, so the copy runs off the end
    of everything. The corrected variants are instructive about what the
    discriminator has to be: one fixes the *source* (`data = 100-1`) and the
    other keeps the negative source and adds `if (data > 0)`. So neither the
    assignment alone nor the call alone separates them -- only "can be
    negative, and nothing has ruled that out by the time it is used".

    An upper bound is not a guard here, and treating `data < 100` as one would
    silence the flawed variant along with the fixed one.
    """
    for start, end in _c_function_spans(ctx.code):
        signed: set[str] = set()
        risky: dict[str, int] = {}
        for index in range(start, end + 1):
            line = ctx.code[index]

            declared = SIGNED_DECL.match(line)
            if declared:
                signed.add(declared.group(1))

            guard = NONNEGATIVE_GUARD.search(line)
            if guard:
                risky.pop(guard.group(1) or guard.group(2), None)

            negative = NEGATIVE_ASSIGN.match(line)
            if negative and negative.group(1) in signed:
                risky[negative.group(1)] = index
            else:
                source = COMMAND_TAINT_SOURCE.search(line)
                if source:
                    # `fscanf(stdin, "%hd", &data)` fills a signed variable
                    # with whatever was typed, which includes negatives.
                    for name in re.findall(r"&\s*(\w+)", line):
                        if name in signed:
                            risky[name] = index
                target = _ASSIGN_TARGET.match(line)
                if target and target.group(1) in signed and not negative:
                    # Reassigned from something that is not a negative
                    # literal; no longer known to be negative.
                    if not source:
                        risky.pop(target.group(1), None)

            if not risky:
                continue
            call = SIZE_CALL.search(line)
            if not call:
                continue
            position = SIZE_SINKS[call.group(1)]
            arguments = _split_arguments(line[call.end():])
            if len(arguments) <= position:
                continue
            candidate = arguments[position].strip()
            if candidate in risky:
                yield _f(ctx, index, "c-signed-size", "HIGH",
                         "'%s' is signed and may be negative here; passing it "
                         "as the size argument of %s converts it to an "
                         "enormous unsigned value."
                         % (candidate, call.group(1)), r_signed_size.fix)
                risky.pop(candidate, None)

#!/usr/bin/env python3
"""
fixmemory.py -- durable memory for repeated safe repair patterns.

When evolve.py sees the same mechanical fix across harvested code, Attestor can
record it as a known repair pattern with counts and examples. This is not model
training; it is a plain, inspectable JSON memory.
"""
from __future__ import annotations

import argparse
import json
import os
import time

DEFAULT_MEMORY = os.path.join(os.path.dirname(os.path.abspath(__file__)), "attestor_fix_memory.json")


def load(path: str = DEFAULT_MEMORY) -> dict:
    if not os.path.exists(path):
        return {"version": 1, "patterns": {}}
    with open(path, encoding="utf-8") as fh:
        return json.load(fh)


def save(memory: dict, path: str = DEFAULT_MEMORY) -> str:
    os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
    with open(path, "w", encoding="utf-8") as fh:
        json.dump(memory, fh, indent=2, sort_keys=True)
        fh.write("\n")
    return path


def learn(memory: dict, rid: str, note: str, count: int, source: dict | None = None) -> dict:
    key = note or rid
    patterns = memory.setdefault("patterns", {})
    rec = patterns.setdefault(key, {
        "rule": rid,
        "note": note,
        "count": 0,
        "sources": [],
        "first_seen": time.strftime("%Y-%m-%d"),
        "last_seen": "",
        "promoted": False,
    })
    rec["count"] += int(count)
    rec["last_seen"] = time.strftime("%Y-%m-%d")
    if source:
        example = {
            "repo": source.get("repo") or "unknown",
            "path": source.get("path") or "unknown",
            "url": source.get("url") or "",
        }
        if example not in rec["sources"]:
            rec["sources"].append(example)
        rec["sources"] = rec["sources"][-10:]
    if rec["count"] >= 3:
        rec["promoted"] = True
    return rec


def learn_from_evolve_run(run: dict, path: str = DEFAULT_MEMORY) -> dict:
    memory = load(path)
    for result in run.get("results", []):
        source = result.get("source", {})
        for rid, count, note in result.get("applied", []):
            learn(memory, rid, note, count, source)
    save(memory, path)
    return memory


def render(memory: dict) -> str:
    patterns = memory.get("patterns", {})
    out = ["Fix Memory", "=" * 10]
    if not patterns:
        out.append("No repair patterns recorded yet.")
        return "\n".join(out)
    for key, rec in sorted(patterns.items(), key=lambda item: (-item[1].get("count", 0), item[0])):
        badge = "known repair" if rec.get("promoted") else "observed"
        out.append("  %s x%d [%s] %s" % (
            rec.get("rule") or "unknown", rec.get("count", 0), badge, key))
    return "\n".join(out)


def main(argv=None) -> int:
    ap = argparse.ArgumentParser(
        description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--memory", default=DEFAULT_MEMORY)
    args = ap.parse_args(argv)
    print(render(load(args.memory)))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

def bug_oracle(files: list[str]) -> list[str]:
    """Combine semantic findings with risk-shape predictions."""
    out = []
    for path in files:
        source = _read(path)
        findings = deepscan.analyze(source, path)
        for finding in findings[:5]:
            out.append("%s:%d [%s] %s -> %s" % (
                path, finding.line, finding.severity, finding.rule, finding.fix))
        fg, _findings, funcs = grade.grade_source(source, path, metrics.DEFAULT_LIMITS)
        if fg.score < 90:
            out.append("%s code-health prediction: %s %d/100; review before extending." % (
                path, fg.grade, fg.score))
        if any(item.cognitive >= 10 for item in funcs):
            out.append("%s future-bug risk: high cognitive complexity concentrates defects." % path)
    return out[:MAX_ITEMS] or ["no semantic findings or strong risk-shapes found."]

