    for src, dst in examples:
        if len(src) != len(dst):
            continue
        allowed = set(space)
        for i in range(len(src)):
            valid = {k for k in allowed
                     if factory(k)(bytes([src[i]])) == bytes([dst[i]])}
            candidates = valid if candidates is None \
                else (candidates & valid)
            if not candidates:
                break
        if candidates is not None and not candidates:
            continue
    if not candidates:
        return []
    return sorted(candidates)[:4]

def google_search(query: str):
    """Real Google search via the official Custom Search JSON API.

    Returns {"available": bool, ...}. Needs GOOGLE_API_KEY + GOOGLE_CX (a Custom
    Search Engine id) in the environment -- the ToS-compliant way to query Google
    programmatically. The googleapis.com host is reachable through the egress
    proxy, so this genuinely works once those are set; without them (or if the
    host is blocked) Attestor says so plainly instead of pretending.
    """
    global _fetch_budget
    if query in _google_cache:
        return _google_cache[query]
    if not _GOOGLE_KEY or not _GOOGLE_CX:
        res = {"available": False, "note": "set GOOGLE_API_KEY + GOOGLE_CX to enable Google search"}
        _google_cache[query] = res
        return res
    if _fetch_budget <= 0:
        return {"available": False, "note": "fetch budget exhausted"}
    _fetch_budget -= 1
    try:
        from urllib.parse import urlencode
        params = urlencode({"key": _GOOGLE_KEY, "cx": _GOOGLE_CX, "q": query, "num": 1})
        status, body = _get(f"https://www.googleapis.com/customsearch/v1?{params}",
                            accept="application/json", timeout=8)
        data = json.loads(body)
        total = data.get("searchInformation", {}).get("totalResults")
        items = data.get("items") or []
        top = items[0].get("link") if items else None
        res = {"available": True, "total": total, "top": top}
    except urllib.error.HTTPError as e:
        res = {"available": False, "note": f"Google API said {e.code} (key/cx/quota?)"}
    except urllib.error.URLError as e:
        reason = str(getattr(e, "reason", e))
        res = {"available": False,
               "note": "blocked by egress policy" if "403" in reason else f"unreachable ({reason[:40]})"}
    except Exception as e:                    # noqa: BLE001
        res = {"available": False, "note": f"google error ({type(e).__name__})"}
    _google_cache[query] = res
    return res

def _function_nodes(tree: ast.Module) -> list[tuple[str, ast.AST]]:
    """Return top-level functions and class methods for direct call mapping."""
    out = []
    for node in tree.body:
        if isinstance(node, ast.ClassDef):
            for item in node.body:
                if isinstance(item, _DEF):
                    out.append(("%s.%s" % (node.name, item.name), item))
        elif isinstance(node, _DEF):
            out.append((node.name, node))
    return out

def from_detect_finding(finding: Any, cwe_map: dict[str, str] | None = None) -> PocFinding:
    """Adapt a detect.py Finding into a PocFinding."""
    cwe_str = ""
    if cwe_map:
        cwe_str = cwe_map.get(finding.rule, "")
    if not cwe_str and hasattr(finding, "cwe"):
        cwe_str = getattr(finding, "cwe", "")
    cwe_num = 0
    if cwe_str:
        m = re.search(r"(\d+)", str(cwe_str))
        if m:
            cwe_num = int(m.group(1))
    return PocFinding(
        cwe=cwe_num,
        rule=finding.rule,
        file_path=finding.path,
        line=finding.line,
        snippet=getattr(finding, "snippet", ""),
        message=getattr(finding, "message", ""),
    )

def trustworthy(self) -> bool:
        """Signed by a trusted key and currently within its validity window."""
        return self.valid and self.state in {"fresh", "expiry-unknown"}

def parse_profile(value: Any) -> VariantProfile:
    """Resolve a CLI alias or revalidate a compiled profile object.

    API and UI boundaries should call :func:`profile_for_slug`; aliases are
    deliberately a CLI convenience and are not wire-level identifiers.
    """
    if type(value) is VariantProfile:
        return require_compiled_profile(value)
    normalized = _normalize_alias(value)
    slug = ALIASES.get(normalized)
    if slug is None:
        raise VariantError("unknown Attestor 4.1.4 variant")
    return require_compiled_profile(PROFILES[slug])

