def _directory_size(path: str, stop_after: int | None = None) -> int:
    """Best-effort non-symlink-following size used to stop disk-filling code."""
    total = 0
    try:
        for root, _dirs, files in os.walk(path, followlinks=False):
            for name in files:
                try:
                    total += os.stat(os.path.join(root, name), follow_symlinks=False).st_size
                except OSError:
                    continue
                if stop_after is not None and total > stop_after:
                    return total
    except OSError:
        return total
    return total

def safe_text(value: Any, maximum: int = 1_000) -> str:
    """Return display-safe bounded text without raw terminal/bidi controls."""
    if type(maximum) is not int or maximum < 0:
        raise ValidationError("text boundary is invalid")
    output: list[str] = []
    used = 0
    for character in str(value or ""):
        code = ord(character)
        token = (f"\\u{code:04x}" if
                 code < 0x20 or 0x7F <= code <= 0x9F or character in _BIDI
                 else character)
        encoded = len(token.encode("utf-8"))
        if used + encoded > maximum:
            break
        output.append(token)
        used += encoded
    return "".join(output)

