def _validate_ollama_host(host: str, allow_remote: bool = False) -> str:
    """Validate an Ollama base URL and return a normalized value.

    Local loopback endpoints are the safe default. A remote endpoint requires
    the explicit ``ATTESTOR_ALLOW_REMOTE_OLLAMA=1`` trust decision.
    """
    raw = (host or "http://localhost:11434").strip()
    try:
        parsed = urllib.parse.urlsplit(raw)
        _ = parsed.port
    except ValueError as exc:
        raise ProviderConfigurationError("invalid OLLAMA_HOST") from exc
    hostname = (parsed.hostname or "").rstrip(".").lower()
    if parsed.scheme not in ("http", "https") or not hostname:
        raise ProviderConfigurationError("OLLAMA_HOST must be a full http(s) URL")
    if parsed.username is not None or parsed.password is not None:
        raise ProviderConfigurationError("OLLAMA_HOST must not contain credentials")
    if parsed.path not in ("", "/") or parsed.query or parsed.fragment:
        raise ProviderConfigurationError("OLLAMA_HOST must not contain a path, query, or fragment")
    if any(ch in raw for ch in "\x00\r\n"):
        raise ProviderConfigurationError("invalid OLLAMA_HOST")
    if not _loopback_host(hostname) and not allow_remote:
        raise ProviderConfigurationError(
            "remote OLLAMA_HOST blocked; set ATTESTOR_ALLOW_REMOTE_OLLAMA=1 only for a trusted server")
    if _loopback_host(hostname):
        _validate_loopback_resolution(
            hostname, parsed.port or (443 if parsed.scheme == "https" else 80))
    return raw.rstrip("/")

#!/usr/bin/env python3
"""
nativepool.py -- run a per-file scan across all your cores.

Every native engine here processes one file independently, so scanning a tree is
embarrassingly parallel. This is the shared helper: pmap(func, items, jobs) fans
the work out over a process pool (stdlib multiprocessing, zero dependencies) and
falls back to a plain serial map for jobs<=1 or a single item. Nothing else about
the engines changes -- they just finish sooner on a big codebase.
"""
from __future__ import annotations

import multiprocessing
import os


def default_jobs() -> int:
    return os.cpu_count() or 1


def resolve(jobs) -> int:
    """Turn a --jobs value into a worker count: 0 (or None) means 'all cores'."""
    if not jobs:
        return default_jobs()
    return max(1, int(jobs))


def pmap(func, items, jobs) -> list:
    """Map func over items, in parallel when it pays off. func must be a top-level
    (picklable) function. Order of results matches order of items."""
    items = list(items)
    workers = resolve(jobs)
    if workers <= 1 or len(items) <= 1:
        return [func(item) for item in items]
    with multiprocessing.Pool(processes=workers) as pool:
        return pool.map(func, items)

def _releases(line):
    """(routine, name) for a release on this line, or None."""
    match = C_RELEASE.search(line)
    if not match:
        return None
    for group, offset in (("free", 2), ("delarr", 4), ("del", 6)):
        if match.group(group):
            return group, match.group(offset)
    return None

def _project_finding(row: Any) -> dict[str, Any] | None:
    """Retain exactly the scalar finding fields Truth Guard 1 consumes."""
    if type(row) is not dict:
        return None
    projected: dict[str, Any] = {}
    for key in ("rule", "rule_id", "ruleId", "path", "line",
                "severity", "fingerprint"):
        value = row.get(key)
        if value is None or isinstance(value, (str, bool, int, float)):
            if key in row:
                projected[key] = value
    return projected

class FileChange:
    """Add (hash=None), update, or delete (content=None) one regular file."""

    path: str
    before_sha256: str | None
    new_content: bytes | str | None

    def __post_init__(self) -> None:
        object.__setattr__(self, "path", normalize_relative_path(self.path))
        if self.before_sha256 is not None:
            digest = str(self.before_sha256).lower()
            if not _SHA_RE.fullmatch(digest):
                raise RepairError("before_sha256 must be a lowercase SHA-256 digest")
            object.__setattr__(self, "before_sha256", digest)
        if isinstance(self.new_content, str):
            object.__setattr__(self, "new_content",
                               self.new_content.encode("utf-8", "strict"))
        elif self.new_content is not None and not isinstance(self.new_content, bytes):
            raise RepairError("new_content must be bytes, text, or None")
        if self.before_sha256 is None and self.new_content is None:
            raise RepairError("an absent file cannot be deleted")

    @property
    def operation(self) -> str:
        if self.before_sha256 is None:
            return "add"
        if self.new_content is None:
            return "delete"
        return "update"

    @property
    def after_sha256(self) -> str | None:
        return _sha(self.new_content) if self.new_content is not None else None

def _unplanned_entries(target: str, planned,
                       prior_generated=frozenset()) -> list:
    """Files in the output directory that this run would not rewrite.

    Only consulted when the directory is *not* recognisably a previous
    generation.  Anything this returns is content the caller would lose
    silently, so it is worth naming before the delete rather than after it.
    """
    expected = {os.path.normcase(path) for path in planned}
    unexpected = []
    for root, dirs, names in os.walk(target):
        dirs[:] = [name for name in dirs if name not in _DERIVED_DIRS]
        for name in names:
            full = os.path.join(root, name)
            if os.path.normcase(full) in expected:
                continue
            relative = os.path.relpath(full, target).replace(os.sep, "/")
            if relative in prior_generated:
                continue
            if name.endswith(_DERIVED_SUFFIXES):
                continue
            unexpected.append(relative)
            if len(unexpected) > 64:
                return sorted(unexpected)
    return sorted(unexpected)

