                "contained": 0,
            },
        }
        return {**body, "report_sha256": _sha(body)}
    results = [_solve(item) for item in _selected(selection)]
    escapes = sum(row["escaped_simulation"] is True for row in results)
    body = {
        **base,
        "status": "simulated-escape-demonstrated" if escapes else "contained",
        "simulation_confirmed": True,
        "scenario_results": results,
        "summary": {
            "scenarios": len(results),
            "simulated_escapes": escapes,
            "contained": len(results) - escapes,
        },
    }
    return {**body, "report_sha256": _sha(body)}

def _render_calls(edges: list[tuple[str, str]]) -> list[str]:
    """Render direct call graph edges, including the empty graph case."""
    if not edges:
        return ["  no direct in-module calls between public functions/methods found."]
    return ["  %s -> %s" % (caller, callee) for caller, callee in edges]

def from_env(mode: str = "fallback", model: str = "", exclude=()) -> Brain:
    """Build a Brain from whatever keys are in the environment.

    `model`, if given, overrides the model on every configured provider -- handy
    for a single-provider setup (e.g. just Groq running Qwen). `exclude` drops
    providers by name (e.g. exclude=("gemini",) to bench Google AI Studio).
    Keys in a `keys.env` file are loaded first (a real env var still wins).
    """
    import envfile
    envfile.load()
    providers = []
    configuration_errors = []

    def add(name, factory):
        try:
            providers.append(factory())
        except ProviderConfigurationError as exc:
            configuration_errors.append(name + ": " + str(exc))

    # Order = reliability of the free tier: the sturdy ones first, flaky Gemini
    # later, paid OpenAI last. In fallback mode a 429 on any one cascades to the
    # next, so this is the "escape Google's 429s" chain, automatic.
    groq_key = os.environ.get("GROQ_API_KEY")
    if groq_key:
        add("groq", lambda: GroqProvider(
            groq_key, os.environ.get("GROQ_MODEL", "llama-3.3-70b-versatile")))
    openrouter_key = os.environ.get("OPENROUTER_API_KEY")
    if openrouter_key:
        add("openrouter", lambda: OpenRouterProvider(
            openrouter_key,
            os.environ.get("OPENROUTER_MODEL", "meta-llama/llama-3.3-70b-instruct:free")))
    mistral_key = os.environ.get("MISTRAL_API_KEY")
    if mistral_key:
        add("mistral", lambda: MistralProvider(
            mistral_key, os.environ.get("MISTRAL_MODEL", "mistral-small-latest")))
    gemini_key = os.environ.get("GEMINI_API_KEY") or os.environ.get("GOOGLE_API_KEY")
    if gemini_key:
        add("gemini", lambda: GeminiProvider(
            gemini_key, os.environ.get("GEMINI_MODEL", "gemini-2.0-flash")))
    openai_key = os.environ.get("OPENAI_API_KEY")
    if openai_key:
        add("openai", lambda: OpenAIProvider(
            openai_key, os.environ.get("OPENAI_MODEL", "gpt-4o-mini")))
    # Ollama last: local, keyless, never rate-limited -- the backstop that answers
    # when every cloud tier is throttled. Enabled by naming a local model.
    ollama_model = os.environ.get("OLLAMA_MODEL")
    if ollama_model:
        allow_remote = os.environ.get("ATTESTOR_ALLOW_REMOTE_OLLAMA", "").strip().lower() in {
            "1", "true", "yes", "on"
        }
        add("ollama", lambda: OllamaProvider(
            ollama_model, os.environ.get("OLLAMA_HOST", "http://localhost:11434"),
            allow_remote=allow_remote))
    if exclude:
        providers = [p for p in providers if p.name not in exclude]
    if model:
        try:
            checked_model = _validate_model(model)
        except ProviderConfigurationError as exc:
            configuration_errors.append("model override: " + str(exc))
            providers = []
        else:
            for provider in providers:
                provider._model = checked_model
    return Brain(providers, mode, configuration_errors)

def _fnv1a(text: str) -> int:
    """Deterministic 32-bit hash. `hash()` is randomised and unusable here."""
    value = _FNV_OFFSET
    for byte in text.encode("utf-8", "replace"):
        value = ((value ^ byte) * _FNV_PRIME) & _MASK32
    return value

def map_findings_to_threats(model: Mapping[str, Any],
                            findings: Sequence[Mapping[str, Any]]) -> list[dict[str, Any]]:
    """Bind measured analyzer findings to the threats that were modelled.

    A finding is linked to a category when its rule contains one of that
    category's hint tokens. The link is evidence (`basis: measured`); it does not
    by itself mean the threat is realised, only that there is something to weigh.
    """
    if not isinstance(model, Mapping) or model.get("schema") != MODEL_SCHEMA:
        raise ThreatModelError("expected a threat model")
    categories = {t.get("category") for t in (model.get("threats") or [])}
    links = []
    for f in findings:
        rule = str(f.get("rule", "")).lower()
        for category in STRIDE:
            if category not in categories:
                continue
            for hint in CATEGORY_HINTS[category]:
                if hint in rule:
                    links.append({
                        "category": category,
                        "basis": "measured",
                        "finding_rule": str(f.get("rule", "")),
                        "finding_line": f.get("line"),
                        "severity": f.get("severity"),
                    })
                    break
    return links

def _header_name(header: str):
    """The callable a '{'-opening header names, or None if it isn't a function."""
    match = _FUNC_HEADER.search(header)
    if match and match.group(1) not in _CONTROL_SET:
        return match.group(1)
    return None

