def verify(case: Any) -> tuple[bool, list[str]]:
    """Re-derive the chain. Returns (ok, problems); never raises on hostile input."""
    problems: list[str] = []
    try:
        if not isinstance(case, Mapping) or case.get("schema") != CASE_SCHEMA:
            return False, ["not a case file"]
        entries = case.get("entries")
        if not isinstance(entries, list):
            return False, ["entries is not a list"]

        previous = GENESIS
        for position, entry in enumerate(entries):
            if not isinstance(entry, Mapping):
                problems.append("entry %d is not a mapping" % position)
                break
            if entry.get("index") != position:
                problems.append("entry %d has index %r" % (position, entry.get("index")))
            if entry.get("prev_sha256") != previous:
                problems.append("entry %d does not chain to its predecessor" % position)
            body = {k: v for k, v in entry.items() if k != "entry_sha256"}
            expected = _entry_digest(body, entry.get("prev_sha256", ""))
            if entry.get("entry_sha256") != expected:
                problems.append("entry %d digest does not match its content" % position)
            if entry.get("stage") == "regression" and \
                    (entry.get("evidence") or {}).get("fails_before_fix") is not True:
                problems.append("entry %d is a regression without a pre-fix failure" % position)
            previous = entry.get("entry_sha256", "")
        return (not problems), problems
    except Exception as exc:  # noqa: BLE001 - hostile input must not escape as a crash
        return False, ["verification failed closed (%s)" % type(exc).__name__]

def _fixed_drive_roots() -> tuple[list[Path], list[str]]:
    """Return local fixed drives only; never removable or network drives."""
    if os.name != "nt":
        return [Path(os.path.abspath(os.sep))], [
            "portable fixed-drive enumeration covers only the primary filesystem root"
        ]
    try:
        import ctypes
        kernel32 = ctypes.windll.kernel32
        mask = int(kernel32.GetLogicalDrives())
        roots: list[Path] = []
        for index in range(26):
            if not mask & (1 << index):
                continue
            root = "%s:\\" % chr(ord("A") + index)
            # DRIVE_FIXED == 3.  Network (4), removable (2), CD-ROM (5),
            # RAM disk (6), and unknown/no-root types are deliberately denied.
            if int(kernel32.GetDriveTypeW(root)) == 3:
                roots.append(Path(root))
        return roots, ([] if roots else ["no local fixed drive was available"])
    except (AttributeError, OSError, TypeError, ValueError):
        return [], ["local fixed-drive enumeration failed closed"]

def run_scored(fn, data, distances, allowed):
    """Single tracer pass: collect entered function names, line coverage,
    and crash info in one execution."""
    entered = set()
    covered = set()

    def tracer(frame, event, arg):
        if event == "call":
            entered.add(frame.f_code.co_name)
            return tracer
        if event == "line":
            covered.add((id(frame.f_code), frame.f_lineno))
            return tracer
        return None

    import sys
    previous = sys.gettrace()
    sys.settrace(tracer)
    crash = None
    try:
        fn(bytes(data))
    except allowed:
        pass
    except Exception as exc:  # noqa: BLE001
        crash = {"exception": "%s: %s" % (type(exc).__name__, exc)}
    finally:
        sys.settrace(previous)

    best = INF
    for name in entered:
        best = min(best, distances.get(name, INF))
    return best, covered, crash

def _physical_memory_bytes() -> int | None:
    """Total RAM, or None when the platform will not say without a dependency."""
    # POSIX: the arithmetic is exact and needs nothing installed.
    if hasattr(os, "sysconf"):
