        ]
    })
    .to_string();
    let items = parse_search_items_from_call_result(&call_result_with_json(&payload), "literal");
    assert_eq!(items.len(), 1);
    assert_eq!(items[0].chunk_id, Some(7));
}

#[test]
fn parse_semantic_items_keep_real_ids() {
