                out.append(" " * len(line))
                continue
            body, tail = line[:71], " " * max(0, len(line) - 71)
            chars = list(body)
            index, quote, field = 0, None, 0
            while index < len(chars):
                char = chars[index]
                if quote:
                    if char == "'":
                        quote = None
                elif char == "'":
                    quote = char
                elif char == " ":
                    while index < len(chars) and chars[index] == " ":
                        index += 1
