def centrality(graph, alpha_scaled=ALPHA_SCALED):
    """Power iteration on x' = a*M^T x + (1-a)*s, fixed-point 1e6."""
    nodes = graph["nodes"]
    ids = sorted(nodes)
    index = {nid: i for i, nid in enumerate(ids)}
    size = len(ids)

    outgoing = {nid: 0 for nid in ids}
    for src, dst in graph["edges"]:
        outgoing[src] += 1

    # column-normalized adjacency, row-major over targets
    m_rows = [[0] * size for _ in range(size)]
    for src, dst in graph["edges"]:
        if outgoing[src]:
            m_rows[index[dst]][index[src]] = SCALE // outgoing[src]

    seed = []
    total_sev = 0.0
    for nid in ids:
        sev = float(nodes[nid].get("severity", 0.5))
        seed.append(sev)
        total_sev += sev
    if total_sev <= 0:
        seed = [1.0 / size] * size
    else:
        seed = [s / total_sev for s in seed]
    s_scaled = [int(round(v * SCALE)) for v in seed]

    x = list(s_scaled)
    one_minus_alpha = SCALE - alpha_scaled
    residual = SCALE
    iterations = 0
    for iterations in range(1, MAX_ITER + 1):
        new_x = []
        for j in range(size):
            acc = 0
            row = m_rows[j]
            for i in range(size):
                if row[i]:
                    acc += x[i] * row[i]
            value = (alpha_scaled * acc // SCALE
                     + one_minus_alpha * s_scaled[j] // SCALE)
            new_x.append(value)
        residual = max(abs(new_x[i] - x[i]) for i in range(size))
        x = new_x
        if residual <= TOL_SCALED:
            break

    norm = sum(x) or 1
    values = {nid: round(x[index[nid]] / norm, 6) for nid in ids}
    return {
        "values": values,
        "iterations_used": iterations,
        "final_residual_scaled": residual,
        "converged": residual <= TOL_SCALED,
        "equation": "x' = 0.85*(M^T x) + 0.15*s, fixed point 1e6",
    }

def _loads_name(node, name):
    """True if `name` is loaded as a free variable in `node`. A nested
    `except ... as name:` handler rebinds `name` locally, so uses inside it are
    that fresh binding, not a leak of the outer one -- those subtrees are skipped
    (otherwise two adjacent try/excepts that reuse the same name false-positive)."""
    if isinstance(node, ast.Name):
        return isinstance(node.ctx, ast.Load) and node.id == name
    if isinstance(node, ast.ExceptHandler) and node.name == name:
        return False
    return any(_loads_name(child, name) for child in ast.iter_child_nodes(node))

def _sig(fn: ast.AST) -> str:
    """Render a def's parameter list roughly the way it reads in source."""
    a = fn.args
    parts = []
    pos = list(a.posonlyargs) + list(a.args)
    ndef = len(a.defaults)
    first_def = len(pos) - ndef
    for i, arg in enumerate(pos):
        s = arg.arg
        if i >= first_def:
            s += "=" + _unparse(a.defaults[i - first_def])
        parts.append(s)
        if a.posonlyargs and i == len(a.posonlyargs) - 1:
            parts.append("/")
    if a.vararg:
        parts.append("*" + a.vararg.arg)
    elif a.kwonlyargs:
        parts.append("*")
    for arg, d in zip(a.kwonlyargs, a.kw_defaults):
        s = arg.arg
        if d is not None:
            s += "=" + _unparse(d)
        parts.append(s)
    if a.kwarg:
        parts.append("**" + a.kwarg.arg)
    return ", ".join(parts)

def _proved_improvement(row) -> tuple[bool, list[str]]:
    """Require the complete deterministic proof bundle before saying VERIFIED."""
    reasons = []
    if not isinstance(row, Mapping):
        return False, ["improvement is not an object"]
    if row.get("accepted") is not True:
        reasons.append("accepted must be the boolean true")
    verification = row.get("verification")
    if not isinstance(verification, Mapping) or verification.get("accepted") is not True:
        reasons.append("verification bundle is missing or refused")
        verification = {}
    if verification.get("compiler_or_parser") != "verified":
        reasons.append("parser/compiler verification is missing")
    if verification.get("new_findings"):
        reasons.append("verification reports new findings")
    if verification.get("new_failures"):
        reasons.append("verification reports new failures")
    probes = row.get("probes")
    if not isinstance(probes, list) or not probes or any(
            not isinstance(probe, Mapping) or probe.get("status") != "passed" for probe in probes):
        reasons.append("required assurance probes are missing or failed")
    selected = row.get("selected_tests", {})
    if isinstance(selected, Mapping) and selected.get("status") in {"failed", "timed-out"}:
        reasons.append("selected tests failed")
    source = row.get("improved_source")
    if not isinstance(source, str) or not source:
        reasons.append("improved source is absent")
    elif secret_guard.scan_text(source, str(row.get("target", "improved-source"))):
        reasons.append("improved source contains credential-like material")
    try:
        resolved = int(row.get("resolved_count", -1))
        remaining = int(row.get("remaining_count", -1))
    except (TypeError, ValueError):
        reasons.append("repair counts are invalid")
    else:
        if resolved != len(verification.get("resolved_findings", [])):
            reasons.append("resolved count contradicts verification evidence")
        if remaining != verification.get("findings_after"):
            reasons.append("remaining count contradicts verification evidence")
    if row.get("reasons"):
        reasons.append("improvement contains refusal reasons")
    return not reasons, reasons

def _c_block_span(code, index):
    """Line range of the body controlled by the statement on `index`."""
    opener = None
    for probe in range(index, min(index + 3, len(code))):
        if "{" in code[probe]:
            opener = probe
            break
        if probe > index and code[probe].strip():
            return (probe, probe)             # single statement, no braces
    if opener is None:
        return (index, index)
    depth = 0
    for probe in range(opener, len(code)):
        depth += code[probe].count("{") - code[probe].count("}")
        if depth <= 0:
            return (opener, probe)
    return (opener, len(code) - 1)

