def tokenize(source: str) -> list[str]:
    """Cheap language-agnostic lexing: identifiers, numbers, and operators."""
    tokens: list[str] = []
    index, length = 0, len(source)
    while index < length:
        char = source[index]
        if char in " \t\r\n":
            index += 1
        elif char in _IDENT:
            start = index
            while index < length and source[index] in _IDENT:
                index += 1
            tokens.append(source[start:index])
        else:
            tokens.append(char)
            index += 1
    return tokens

