def _function_nodes(node: ast.AST) -> Iterable[ast.AST]:
    """Walk one function while excluding nested function and class bodies."""
    stack = list(reversed(getattr(node, "body", [])))
    while stack:
        current = stack.pop()
        yield current
        if isinstance(current, (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda,
                                ast.ClassDef)):
            continue
        stack.extend(reversed(list(ast.iter_child_nodes(current))))

def rule_counts() -> dict[str, int]:
    """Language -> number of rules written specifically for it."""
    counts: dict[str, int] = {}
    for rule in detect.RULES:
        for language in getattr(rule, "langs", ()) or ():
            if language != WILDCARD:
                counts[language] = counts.get(language, 0) + 1
    return counts

def _project_finding(row: Any) -> dict[str, Any] | None:
    """Keep only fields independently consumed for a finding claim."""
    if type(row) is not dict:
        return None
    projected: dict[str, Any] = {}
    for key in ("rule", "rule_id", "ruleId", "path", "line",
                "severity", "fingerprint"):
        value = row.get(key)
        if value is None or isinstance(value, (str, bool, int, float)):
            if key in row:
                projected[key] = value
    return projected

def find_package_type(repo_path):
    """Detect what kind of installable package this is."""
    p = Path(repo_path)
    checks = [
        ("setup.py", "pip install ."),
        ("pyproject.toml", "pip install ."),
        ("setup.cfg", "pip install ."),
        ("requirements.txt", "pip install -r requirements.txt"),
        ("package.json", None),  # npm -- not auto-installed
        ("Cargo.toml", None),     # cargo -- not auto-installed
        ("go.mod", None),         # go -- not auto-installed
    ]
    for filename, install_cmd in checks:
        if (p / filename).exists():
            return {"file": filename, "cmd": install_cmd,
                    "language": "python" if install_cmd else filename}
    # even bare .py repos can be imported if they're on sys.path
    py_files = list(p.rglob("*.py"))[:1]
    if py_files:
        return {"file": "*.py", "cmd": "__path__",
                "language": "python-raw"}
    return {"file": None, "cmd": None, "language": "unknown"}
